package com.bank.fjp;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class FJPIntegrationTest {

    // ═══ CF default = commonPool ═══
    @Test
    void cf_defaultIsCommonPool() throws Exception {
        AtomicReference<String> threadName = new AtomicReference<>();
        CompletableFuture.runAsync(() ->
            threadName.set(Thread.currentThread().getName())
        ).get();

        assertThat(threadName.get()).contains("ForkJoinPool.commonPool");
    }

    // ═══ CF with custom pool ═══
    @Test
    void cf_customPool() throws Exception {
        ExecutorService myPool = Executors.newFixedThreadPool(2);
        AtomicReference<String> threadName = new AtomicReference<>();

        CompletableFuture.runAsync(() ->
            threadName.set(Thread.currentThread().getName()), myPool
        ).get();

        assertThat(threadName.get()).startsWith("pool-");  // custom, not FJP!
        myPool.shutdown();
    }

    // ═══ parallelStream default = commonPool ═══
    @Test
    void parallelStream_defaultCommonPool() {
        Set<String> threadNames = ConcurrentHashMap.newKeySet();
        IntStream.range(0, 100).parallel().forEach(i -> {
            threadNames.add(Thread.currentThread().getName());
        });

        boolean usesFJP = threadNames.stream().anyMatch(n -> n.contains("ForkJoinPool"));
        assertThat(usesFJP).isTrue();
    }

    // ═══ parallelStream on custom ForkJoinPool ═══
    @Test
    void parallelStream_customFJP() throws Exception {
        ForkJoinPool custom = new ForkJoinPool(2);
        Set<String> threadNames = ConcurrentHashMap.newKeySet();

        custom.submit(() ->
            IntStream.range(0, 100).parallel().forEach(i ->
                threadNames.add(Thread.currentThread().getName()))
        ).get();

        // Should use custom pool threads
        System.out.println("Threads used: " + threadNames);
        custom.shutdown();
    }

    // ═══ CF does NOT fork/join — just uses pool as executor ═══
    @Test
    void cf_noForkJoinSplitting() throws Exception {
        // CF submits a single task — no recursive splitting!
        String result = CompletableFuture.supplyAsync(() -> "single-task").get();
        assertThat(result).isEqualTo("single-task");
        // Work-stealing still helps: idle workers pick up queued CFs!
    }
}
